int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf)
{
    struct smb_hdr *smb;
    struct smb_composite_search_req *req;
    struct smb_composite_search_rsp *rsp;
    int rc = 0;
    int bytes_returned = 0;

    smb = cifs_ses_alloc(xid, tcon->ses, SMB_COMPOSITE_SEARCH);
    if (!smb)
        return -ENOMEM;

    req = (struct smb_composite_search_req *)((char *)smb + sizeof(struct smb_hdr));

    req->searchHandle = searchHandle;

    rc = SendReceive2(xid, tcon, (struct smb_hdr *)smb, &rsp, &bytes_returned);
    if (rc)
        goto out;

    if (bytes_returned < sizeof(struct smb_composite_search_rsp)) {
        rc = -EINVAL;
        goto out;
    }

    psrch_inf->searchHandle = le16_to_cpu(rsp->searchHandle);
    psrch_inf->eof = le32_to_cpu(rsp->eof);

    if (psrch_inf->eof) {
        psrch_inf->endOfSearch = true;
    } else {
        psrch_inf->endOfSearch = false;
    }

out:
    kfree(smb);
    return rc;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    int rc = -EFAULT;

    if (!tcon || !psrch_inf)
        return -EINVAL;

    if (psrch_inf->endOfSearch)
        return 0;

    rc = CIFSSMBSearchNext(xid, tcon, searchHandle, psrch_inf);
    if (rc) {
        psrch_inf->endOfSearch = true;
        return rc;
    }

    if (psrch_inf->entries_in_buffer == 0)
        psrch_inf->endOfSearch = true;

    return 0;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle,
                     struct cifs_search_info *psrch_inf) {
    struct smb2_search_request *srch_req;
    struct smb2_search_response *srch_rsp;
    int rc = 0;

    srch_req = cifs_smb2_allocate_search_request(tcon, searchHandle, 0);
    if (!srch_req)
        return -ENOMEM;

    rc = cifs_smb2_call(xid, tcon, (struct smb2_ioctl_req *) srch_req,
                        sizeof(*srch_req), &srch_rsp);
    if (rc) {
        cifs_smb2_free_search_request(srch_req);
        return rc;
    }

    psrch_inf->entries_received = srch_rsp->entriesReturned;
    psrch_inf->end_of_search = srch_rsp->endOfSearch;

    if (srch_rsp->endOfSearch)
        psrch_inf->search_instance->end = true;

    cifs_smb2_free_search_request(srch_req);
    return 0;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf) {
    struct smb2_search_request *req;
    struct smb2_search_response *resp;
    int rc = 0;

    req = cifs_buf_get();
    if (!req) {
        return -ENOMEM;
    }

    init_smb2_search(req, tcon, searchHandle, psrch_inf);
    rc = SendReceive(xid, tcon, (struct smb2_ioctl_request *)req, (struct smb2_ioctl_response **)&resp, 0);
    if (rc) {
        cifs_buf_release(req);
        return rc;
    }

    psrch_inf->entries_remaining = resp->entries_remaining;
    psrch_inf->last_search_id = resp->search_id;

    if (resp->entries_remaining == 0) {
        psrch_inf->end_of_search = true;
    }

    cifs_buf_release(req);
    return 0;
}

int cifs_search_next(int xid, struct cifs_tcon *tcon, __u16 searchHandle, struct cifs_search_info *psrch_inf)
{
    struct smb_hdr *smb;
    int rc = 0;
    __u16 params, byte_count;

    /* Initialize SMB request */
    rc = smb_init(SMB_COM_SEARCH, tcon, 0, 0, (void **)&smb);
    if (rc) {
        return rc;
    }

    smb->Flags2 |= SMBFLG2_UNICODE;
    params = 0;
    byte_count = 0;

    /* Set up search next request parameters */
    put_unaligned_le16(searchHandle, &smb->Data[params]);
    params += 2;

    byte_count += params;
    byte_count += 0;

    smb->hdr.Len = cpu_to_le16(params + byte_count);
    rc = SendReceive(xid, tcon->ses, smb, 0);
    if (rc) {
        return rc;
    }

    /* Process the response */
    if (smb->Status.Class != 0 || smb->Status.Code != 0) {
        return -EIO;
    }

    if (smb->Data[0] == 0) {
        psrch_inf->endOfSearch = true;
    }

    return 0;
}
